def clean(df):
    df['flipper_length_mm'] = pd.to_numeric(df['flipper_length_mm'])
    df['body_mass_g'] = pd.to_numeric(df['body_mass_g'])
    df = df[(df['body_mass_g'] >= 2500) & (df['body_mass_g'] <= 6500)]
    df['species'] = df['species'].str.lower()
    df['island'] = df['island'].str.strip()
    return df.dropna(subset=['sex'])

def answer(df):
    return df.groupby('sex')['body_mass_g'].mean().to_dict()
